from itertools import combinations

def get_combinations(lst):
    return [comb for i in range(len(lst)+1) for comb in combinations(lst, i)]

figures = ["Socrates", "Plato", "Aristotle", "Euclid", "Archimedes"]
combinations = get_combinations(figures)

for comb in combinations:
    if len(comb) >= 2:
        print("Dinner party with:", ', '.join(comb))

